contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 reqID_, uint256 loanID_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        // Create a request as owner so that a loan can exist.
        c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        // Clear the request as the test contract (msg.sender), creating loan loanID_ = 0.
        c.clearRequest(reqID_, false, false); if (__ESBMC_reverted()) return;

        // Read the public state before the deciding call.
        bool loanExistsBefore = (loanID_ == 0);
        bool activeBefore = c.isActive(reqID_); if (__ESBMC_reverted()) return;
        bool expiredBefore = c.isDefaulted(loanID_); if (__ESBMC_reverted()) return;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // The deciding call: rollLoan(loanID_).
        bool rolled;
        c.rollLoan(loanID_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            rolled = false;
        } else {
            rolled = true;
        }

        // rollLoan should succeed exactly when: the loan exists, the caller is owner,
        // the loan is not expired, and the loan's request is active.
        bool expectedRoll = loanExistsBefore && msg.sender == ownerBefore && !expiredBefore && activeBefore;
        assert(rolled == expectedRoll);
    }

    receive() external payable {}
}

