pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID_, uint256 loanID_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        try c.clearRequest(reqID_, false, false) {} catch { return; }
        bool loanExistsBefore = (loanID_ == 0);
        bool activeBefore;
        try c.isActive(reqID_) returns (bool __r) { activeBefore = __r; } catch { return; }
        bool expiredBefore;
        try c.isDefaulted(loanID_) returns (bool __r) { expiredBefore = __r; } catch { return; }
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool rolled;
        try c.rollLoan(loanID_) {
            rolled = true;
        } catch {
            rolled = false;
        }
        bool expectedRoll = loanExistsBefore && msg.sender == ownerBefore && !expiredBefore && activeBefore;
        assertTrue(rolled == expectedRoll);
    }

    function testFuzz_run(uint256 reqID_, uint256 loanID_, uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        _run(reqID_, loanID_, amount_, interest_, loanToCollateral_, duration_);
    }

    receive() external payable {}
}
